/* B16/B17：平台账号申请及本人进度。准入前没有组织会话，审核结果只由独立演示场景载入。 */
(()=>{
const {esc:E,icon:I,badge:B}=UI,key='aisports-ui-organization-v1';
const blank=()=>({status:'none',form:{name:'',contact:'',channel:'',note:''},versions:[]});
let state;try{state=JSON.parse(localStorage.getItem(key))||blank()}catch{state=blank()}
const labels={none:'尚未申请',draft:'草稿',pending:'待平台审核',rejected:'未通过',approved:'已开放办赛'};
const editable=()=>['none','draft','rejected'].includes(state.status);
const persist=()=>localStorage.setItem(key,JSON.stringify(state));
const now=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',dateStyle:'short',timeStyle:'medium'}).format(new Date());
const crumb=title=>`<div class="small muted org-crumb">平台账号 ${I('chevron')} 我要办赛 ${I('chevron')} ${title}</div>`;
const steps=()=>`<ol class="org-steps">${['填写申请','平台审核','进入办赛工作台'].map((t,i)=>`<li class="${i===0||i===1&&state.versions.length||i===2&&state.status==='approved'?'reached':''}"><span>${i+1}</span>${t}</li>`).join('')}</ol>`;
function shell(body,active){const context=state.status==='approved'?'办赛服务 · 本人准入记录':'办赛服务 · 平台账号';BShell.render({body:`<nav class="b-tabs" aria-label="办赛服务"><a href="#apply" class="${active==='apply'?'active':''}" ${active==='apply'?'aria-current="page"':''}>办赛申请</a><a href="#status" class="${active==='status'?'active':''}" ${active==='status'?'aria-current="page"':''}>审核进度与记录</a></nav>${body}<section class="scenario org-demo"><span>${I('settings')} 原型状态预览</span><select id="org-scenario" aria-label="办赛申请演示状态"><option value="">切换示例状态</option><option value="none">尚未申请（清空示例）</option><option value="pending">待审核</option><option value="rejected">未通过</option><option value="approved">已开放办赛</option><option value="unknown">提交结果待核对</option><option value="failed">进度查询失败</option><option value="expired">会话已失效</option></select><p>仅载入示例结果，不是申请人审批按钮；超级管理员在 RuoYi 审核，本原型暂不展示该操作页。</p></section>`,sidebar:`<span class="sidebar-label">办赛服务</span><a class="sidebar-item ${active==='apply'?'active':''}" href="#apply">${I('file')} 办赛申请</a><a class="sidebar-item ${active==='status'?'active':''}" href="#status">${I('clock')} 审核进度与记录</a><span class="sidebar-label">业务空间</span>${state.status==='approved'?`<a class="sidebar-item" href="business.html#workspace/overview">${I('calendar')} 赛事运营 ${I('arrow')}</a>`:`<span class="sidebar-item sidebar-locked" aria-disabled="true">${I('lock')} 赛事运营 · 准入后开放</span>`}`,context,active,approved:state.status==='approved',prototype:'界面原型 · 示例平台账号 · 本地模拟申请，不提交真实资料',note:'准入审核只决定是否开放办赛；实际业务由服务端核验账号、组织及用途权限。'})}

function formPage(){if(!editable()){location.hash='#status';return}const f=state.form;shell(`${crumb('填写申请')}<div class="section-head"><div><span class="eyebrow">我要办赛</span><h1 class="b-page-title">申请开通办赛空间</h1><p class="muted small mt">完成组织申请，通过平台审核后即可进入赛事运营。</p></div>${B(labels[state.status],'gray')}</div>${steps()}${state.status==='rejected'?`<div class="notice warn org-reason">${I('info')}<span><strong>上一版未通过</strong><br>${E(state.versions.at(-1).reason)}。修改后可再次提交，原版本与审核记录保留。</span></div>`:''}<div class="org-form-grid"><section class="card"><div class="section-head"><h3>组织与联系信息</h3><span class="small muted">* 为提交必填</span></div><form id="organization-form" novalidate><label class="label"><span>组织名称 <b>*</b></span><input name="name" maxlength="200" value="${E(f.name)}" placeholder="填写实际办赛组织名称"></label><div class="grid2"><label class="label"><span>联系人 <b>*</b></span><input name="contact" maxlength="100" value="${E(f.contact)}" placeholder="本次申请联系人"></label><label class="label"><span>联系方式 <b>*</b></span><input name="channel" maxlength="50" value="${E(f.channel)}" placeholder="手机、电话或其他可联系渠道"></label></div><label class="label"><span>申请说明 · 选填</span><textarea name="note" maxlength="1000" rows="4" placeholder="可说明计划举办的运动项目、赛事与组织情况">${E(f.note)}</textarea></label><div class="org-material-note"><span>${I('file')} 附件与资质材料</span><p>当前不要求固定证照清单，申请可无附件提交。材料在线上传入口后置，本原型不收集或上传文件。</p></div><label class="checkline mt"><input name="consent" type="checkbox"><span>我已核对申请内容与联系方式，并知晓审核通过表示平台开放办赛，不表示官方资质认证。</span></label><p class="field-error" id="org-error" role="alert"></p><div class="actions"><button type="button" class="btn" data-org="save">保存草稿</button><button type="submit" class="btn primary">提交申请（模拟） ${I('arrow')}</button></div><p class="entry-note mt">保存草稿允许缺项；正式提交会冻结本版信息，待审期间不可修改。</p></form></section><aside class="stack"><section class="card org-guide"><span class="org-guide-icon">${I('calendar')}</span><h3>组织准入，赛事自主运营</h3><p>申请办赛不要求先建立参赛档案，也不需要重新注册办赛账号。</p><div class="line"></div><h4>通过后可以做什么</h4><p>进入获授权组织，管理赛事、报名与现场执行。具体办理按组织授权开放。</p><h4>审核关注什么</h4><p>平台核对本次申请内容，决定是否开放办赛。没有逐场赛事发布审批。</p><a href="#status" class="btn text">查看我的申请记录 ${I('arrow')}</a></section></aside></div>`,'apply');document.getElementById('organization-form').onsubmit=e=>{e.preventDefault();submit()}}
function details(v){return `<dl class="kv org-kv"><dt>组织名称</dt><dd>${E(v.name)||'未填写'}</dd><dt>联系人</dt><dd>${E(v.contact)||'未填写'}</dd><dt>联系方式</dt><dd>${E(v.channel)||'未填写'}</dd><dt>申请说明</dt><dd>${E(v.note)||'未填写'}</dd><dt>附件</dt><dd>本版无附件 · 上传入口后置</dd></dl>`}
function timeline(v){return `<div class="org-timeline"><div><span class="org-dot"></span><strong>申请已提交 · V${v.number}</strong><p>${E(v.submitted)} · 北京时间</p></div><div><span class="org-dot ${v.status==='pending'?'waiting':''}"></span><strong>${v.status==='pending'?'等待平台审核':v.status==='approved'?'平台审核通过':'平台审核未通过'}</strong><p>${v.reviewed?E(v.reviewed)+' · 示例审核结果':'审核结果会显示在本页；没有承诺固定办理时限。'}</p>${v.reason?`<p class="org-decision">审核理由：${E(v.reason)}</p>`:''}</div><div><span class="org-dot ${v.status==='approved'?'':'waiting'}"></span><strong>${v.status==='approved'?'组织空间已开通':'进入办赛工作台'}</strong><p>${v.status==='approved'?'组织、租户和初始授权在同一事务开通；本页只是模拟结果。':'通过准入并获得有效授权后开放。'}</p></div></div>`}
function history(){return `<section class="card"><div class="section-head"><h3>提交版本与审核记录</h3><span class="small muted">${state.versions.length} 个提交版本</span></div><div class="table-scroll"><table><thead><tr><th>版本</th><th>组织名称</th><th>提交时间（北京时间）</th><th>审核结果</th><th>操作</th></tr></thead><tbody>${[...state.versions].reverse().map(v=>`<tr><td>V${v.number}</td><td>${E(v.name)}</td><td>${E(v.submitted)}</td><td>${B(labels[v.status],v.status==='rejected'?'orange':v.status==='pending'?'gray':'')}</td><td><a class="btn text" href="#version/${v.number}">查看该版本</a></td></tr>`).join('')}</tbody></table></div><p class="entry-note mt">草稿不产生提交版本。再次提交新增版本，历史内容和审核理由保留。</p></section>`}
function statusPage(){const v=state.versions.at(-1);if(!v){shell(`${crumb('申请进度')}<h1 class="b-page-title">审核进度与记录</h1>${steps()}<section class="card empty">${I('file')}<h3>${state.status==='draft'?'草稿尚未提交':'还没有办赛申请'}</h3><p>填写组织名称与联系信息，申请开通办赛空间。</p><a class="btn primary mt" href="#apply">${state.status==='draft'?'继续填写申请':'开始申请'}</a></section>`,'status');return}shell(`${crumb('审核进度')}<div class="section-head"><div><span class="eyebrow">本人申请 · 最新提交 V${v.number}</span><h1 class="b-page-title">审核进度与记录</h1></div>${B(labels[state.status],state.status==='rejected'?'orange':state.status==='pending'?'gray':'')}</div>${steps()}<section class="org-result ${state.status}"><span class="org-result-icon">${I(state.status==='approved'?'check':state.status==='pending'?'clock':'info')}</span><div><h2>${state.status==='approved'?'你的办赛空间已开通':state.status==='pending'?'申请已提交，等待平台审核':'本版申请未通过，可修改后重提'}</h2><p>${state.status==='approved'?E(v.name)+' · 示例组织；进入工作台前仍需校验当前有效组织授权。':state.status==='pending'?'当前提交内容已冻结，可以查看本版资料与历史记录。':'审核理由：'+E(v.reason)}</p>${state.status==='approved'?'<a class="btn primary mt" href="business.html?from=organization">进入办赛工作台（模拟） '+I('arrow')+'</a>':state.status==='rejected'?'<a class="btn primary mt" href="#apply">修改申请并重新提交 '+I('arrow')+'</a>':''}</div></section><div class="org-status-grid"><section class="card"><div class="section-head"><h3>本次提交信息</h3><a href="#version/${v.number}" class="btn text">查看完整版本</a></div>${details(v)}</section><section class="card"><h3>办理进度</h3>${timeline(v)}</section></div>${history()}<div class="notice neutral mt">${I('info')}<span>审核通过仅表示平台办赛准入，不代表主体验真、证照有效性或官方资质认证。审核权归 RuoYi 超级管理员，申请人只能查看本人的结果。</span></div>`,'status')}
function versionPage(number){const v=state.versions.find(x=>x.number===number);if(!v){shell(`${crumb('版本详情')}<section class="card empty"><h2>当前账号没有可查看的该版本</h2><a href="#status" class="btn mt">返回申请记录</a></section>`,'status');return}shell(`${crumb('提交版本')}<div class="section-head"><div><span class="eyebrow">只读提交快照</span><h1 class="b-page-title">申请版本 V${v.number}</h1></div><a href="#status" class="btn">返回申请记录</a></div><section class="card mt"><div class="section-head"><h3>${E(v.name)}</h3>${B(labels[v.status],v.status==='rejected'?'orange':'gray')}</div>${details(v)}${timeline(v)}</section><p class="entry-note mt">本页显示该次提交与审核时的信息；后续修改不覆盖历史版本。</p>`,'status')}
function boundary(){const type=state.status;shell(`${crumb('状态核对')}<section class="card empty">${I(type==='expired'?'lock':'info')}<h2>${type==='expired'?'会话已失效':type==='failed'?'暂时无法读取申请进度':'提交结果待核对'}</h2><p>${type==='expired'?'请重新登录后查看本人的申请。':type==='failed'?'读取失败不代表没有申请，请重新查询。':'尚不能确认是否已提交，请先核对结果，避免重复提交。'}</p>${type==='expired'?'<button class="btn primary mt" data-org="login">重新登录（模拟）</button>':'<button class="btn primary mt" data-org="query">重新查询（模拟）</button>'}</section>`,'status')}
function render(){UI.close();if(['unknown','failed','expired'].includes(state.status)){boundary();return}const route=(location.hash||'#apply').slice(1);if(route.startsWith('version/'))versionPage(Number(route.split('/')[1]));else if(route==='status')statusPage();else formPage()}
function readForm(){const f=new FormData(document.getElementById('organization-form'));state.form={name:String(f.get('name')).trim(),contact:String(f.get('contact')).trim(),channel:String(f.get('channel')).trim(),note:String(f.get('note')).trim()};return f}
function submit(){if(!editable())return;const f=readForm();if(!state.form.name||!state.form.contact||!state.form.channel){document.getElementById('org-error').textContent='请填写组织名称、联系人与联系方式。';return}if(!f.has('consent')){document.getElementById('org-error').textContent='请先核对并确认申请内容。';return}state.versions.push({...state.form,number:state.versions.length+1,status:'pending',submitted:now(),reason:''});state.status='pending';persist();location.hash='#status';render();UI.toast('模拟申请已提交；待审版本已冻结。')}
function scenario(type){if(type==='none')state=blank();else{const v={name:'莲池运动社（示例）',contact:'林一（示例）',channel:'示例联系渠道，非真实号码',note:'计划在保定组织多种运动交流赛事。',number:1,status:['approved','rejected'].includes(type)?type:'pending',submitted:'2026-10-07 10:00:00',reason:type==='rejected'?'申请说明尚不足以说明本次办赛计划，请补充说明':''};if(v.status!=='pending')v.reviewed='2026-10-07 14:00:00';state={status:type,form:{name:v.name,contact:v.contact,channel:v.channel,note:v.note},versions:[v]}}persist();location.hash=type==='none'?'#apply':'#status';render()}
document.addEventListener('click',e=>{const a=e.target.closest('[data-org]')?.dataset.org;if(a==='save'&&editable()){readForm();if(state.status!=='rejected')state.status='draft';persist();UI.toast(state.status==='rejected'?'修改已保存，原拒绝版本保留；尚未再次提交。':'草稿已保存，尚未提交审核。')}if(['query','login'].includes(a)){state.status=state.versions.at(-1)?.status||'none';persist();render();UI.toast('已载入模拟查询结果；没有创建新申请。')}});
document.addEventListener('change',e=>{if(e.target.id==='org-scenario'&&e.target.value)scenario(e.target.value)});window.addEventListener('hashchange',()=>{if(document.getElementById('organization-form')&&editable()){readForm();if(state.status==='none'&&Object.values(state.form).some(Boolean))state.status='draft';persist()}render()});window.addEventListener('storage',e=>{if(e.key===key){try{state=JSON.parse(e.newValue)||blank();render()}catch{}}});render();
})();
